-- Sports for organizations listed only as "Multi-sport" (docs/data-fixes/multi-sport-sports.md). Read from each organization's own website, 2026-10-26.
-- Each sport becomes a program on the organization's card (listing 'with_org', with its seasons) and joins its sports so search finds it. NEEDS migration 0015.
-- Safe to run twice: fixed ids, and every insert is skipped when the organization already has a program for that sport.
-- Look first: each line says what to check.

-- Winfield Parks and Recreation Adaptive Athletics (AL): Baseball, Basketball. Source: http://winfieldparkandrec.org/ . LOOK FIRST: Only https fails; http works. Buddy Ball baseball and adaptive basketball described in a 2024 news post
INSERT OR IGNORE INTO programs (id, organization_id, name, sport, sport_key, city, state, state_name, country, seasons_json, kind, listing, verification_status, status, is_public, created_at, updated_at)
  SELECT 'b0fba4f8-ce5f-57f5-bb20-9d9dde2a85cc', o.id, 'Baseball', 'Baseball', 'baseball', o.city, o.state, o.state_name, 'United States', '["spring"]', 'program', 'with_org', 'unverified', 'active', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now')
  FROM organizations o WHERE o.id = '06a17091-1dd8-5fdd-81d3-051035053271' AND NOT EXISTS (SELECT 1 FROM programs WHERE organization_id = o.id AND sport_key = 'baseball');
UPDATE organizations SET sports_json = json_insert(CASE WHEN json_valid(sports_json) AND json_type(sports_json) = 'array' THEN sports_json ELSE '[]' END, '$[#]', 'baseball'), updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now')
  WHERE id = '06a17091-1dd8-5fdd-81d3-051035053271' AND NOT EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(sports_json) AND json_type(sports_json) = 'array' THEN sports_json ELSE '[]' END) WHERE value = 'baseball');
